def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    total_my_d = 0
    total_opp_d = 0
    recent_opp_d_5 = 0
    recent_opp_d_3 = 0
    resp_punish = 0
    resp_forgive = 0

    start5 = n - 5
    if start5 < 0:
        start5 = 0
    start3 = n - 3
    if start3 < 0:
        start3 = 0

    for i in range(n):
        m, o = history[i]
        if m == 'D':
            total_my_d += 1
        if o == 'D':
            total_opp_d += 1
        if i >= start5 and o == 'D':
            recent_opp_d_5 += 1
        if i >= start3 and o == 'D':
            recent_opp_d_3 += 1
        if i > 0:
            prev_m = history[i - 1][0]
            if prev_m == 'D':
                if o == 'D':
                    resp_punish += 1
                else:
                    resp_forgive += 1

    if total_opp_d == 0:
        if total_my_d == 0:
            if n >= 15:
                return 'D'
            return 'C'
        return 'D' if rng.random() < 0.93 else 'C'

    if opp_last == 'C' and resp_punish == 0 and resp_forgive >= 2 and recent_opp_d_5 <= 1:
        return 'D' if rng.random() < 0.72 else 'C'

    if recent_opp_d_5 >= 4 or recent_opp_d_3 == 3 or (n >= 25 and total_opp_d > n // 2 + 2 and recent_opp_d_5 >= 2) or (total_opp_d >= 15 and recent_opp_d_5 >= 3):
        if opp_last == 'C':
            if recent_opp_d_5 <= 3:
                return 'C'
            return 'D'
        if total_my_d >= total_opp_d - 1 and recent_opp_d_5 <= 3:
            return 'C' if rng.random() < 0.4 else 'D'
        return 'D' if rng.random() < 0.9 else 'C'

    if opp_last == 'C':
        if my_last == 'D':
            if total_opp_d <= 2 and recent_opp_d_5 == 0 and total_my_d >= total_opp_d + 3:
                return 'D' if rng.random() < 0.28 else 'C'
            return 'C'
        return 'C'

    if recent_opp_d_5 <= 1 and recent_opp_d_3 <= 1 and total_opp_d <= total_my_d + 3:
        return 'C'

    if total_opp_d <= total_my_d + 1 and recent_opp_d_3 <= 2 and recent_opp_d_5 <= 2:
        return 'C'

    if recent_opp_d_3 >= 2 and total_opp_d > total_my_d + 1:
        return 'D' if rng.random() < 0.9 else 'C'

    if total_opp_d <= total_my_d + 3 and recent_opp_d_5 <= 3:
        return 'C' if rng.random() < 0.55 else 'D'

    return 'D' if rng.random() < 0.8 else 'C'
